use std::{collections::HashMap,fs,path::PathBuf}; use crate::{domain::managed_workload_operation::ManagedWorkloadOperation,storage::{atomic::write_atomic,StorageError}};
#[derive(serde::Serialize,serde::Deserialize,Default)] #[serde(rename_all="camelCase")] struct File{#[serde(default)] operations:HashMap<String,ManagedWorkloadOperation>}
pub struct JsonManagedWorkloadOperationRepository{path:PathBuf}
impl JsonManagedWorkloadOperationRepository{pub fn new(dir:impl Into<PathBuf>)->Self{Self{path:dir.into().join("managed-workload-operations.json")}} fn file(&self)->File{fs::read(&self.path).ok().and_then(|b|serde_json::from_slice::<File>(&b).ok()).filter(|f|f.operations.values().all(ManagedWorkloadOperation::validate)).unwrap_or_default()} pub fn get(&self,device:&str,workload:&str)->Option<ManagedWorkloadOperation>{self.file().operations.remove(&format!("{device}:{workload}"))} pub fn save(&self,op:&ManagedWorkloadOperation)->Result<(),StorageError>{if !op.validate(){return Err(StorageError::Validation("invalid managed workload operation".into()))}let mut f=self.file();f.operations.insert(format!("{}:{}",op.device_id,op.workload_id),op.clone());write_atomic(&self.path,&serde_json::to_vec_pretty(&f)?)?;Ok(())}}
#[cfg(test)] mod tests { use super::*; use crate::domain::managed_workload_operation::*; use tempfile::tempdir; fn op()->ManagedWorkloadOperation{ManagedWorkloadOperation{schema_version:1,id:"op-1".into(),device_id:"pi5".into(),workload_id:"finance".into(),action_id:"personal-finance".into(),config_revision:1,trusted_action_digest:"a".repeat(64),target_revision:"b".repeat(40),deployment_fingerprint:"c".repeat(64),transient_unit_id:None,dispatch_state:ManagedWorkloadDispatchState::NotAttempted,state:ManagedWorkloadOperationState::Prepared,created_at:"x".into(),prepared_at:Some("x".into()),started_at:None,observation_deadline:None,completed_at:None,failure:None}} #[test] fn round_trip_is_bounded_and_secret_free(){let d=tempdir().unwrap();let r=JsonManagedWorkloadOperationRepository::new(d.path());r.save(&op()).unwrap();assert_eq!(r.get("pi5","finance"),Some(op()));let raw=fs::read_to_string(d.path().join("managed-workload-operations.json")).unwrap();assert!(!raw.contains("stdout")&&!raw.contains("/usr/")&&!raw.contains("secret"));} #[test] fn missing_or_malformed_is_safe(){let d=tempdir().unwrap();let r=JsonManagedWorkloadOperationRepository::new(d.path());assert!(r.get("pi5","finance").is_none());fs::write(d.path().join("managed-workload-operations.json"),"bad").unwrap();assert!(r.get("pi5","finance").is_none());} }
